            fn charge(&mut self, amount: usize) -> Result<(), &'static str> {
                if let Some(first) = self.refusal {
                    return Err(first);
                }
                let Some(remaining) = self.remaining.checked_sub(amount) else {
                    self.refusal = Some(self.label);
