//! Final constructor, real Legacy case coordinates, and complete old receivers.
use super::{extend, fixture, Facts};
use crate::hir::{
    DeclarationId, DeclarationIndex, DeclarationKind, IdentityOrigin, LinkedDeclarationFact,
    LinkedOwnedDataParts, LinkedScalarFunction, NominalPayload, ResolvedFunction, ResolvedProgram,
    ResolvedType, ResolvedTypeDeclaration, ResolvedTypeDeclarationKind,
};
use crate::test_allocation_observer::{current_metrics, measure};

fn main_function() -> ResolvedFunction {
    let ast = crate::check(
        "module final.legacy; @id(\"app.main\") fn main()->i64 {0}",
        "final-legacy.spx",
    )
    .unwrap();
    crate::hir::resolve(&ast).unwrap().functions.remove(0)
}
fn final_link(
    types: Vec<ResolvedTypeDeclaration>,
    mut facts: Facts,
    function: ResolvedFunction,
    old: bool,
) -> Result<ResolvedProgram, crate::diagnostic::Diagnostic> {
    facts.insert(
        function.id.clone(),
        LinkedDeclarationFact {
            kind: DeclarationKind::Function,
            origin: IdentityOrigin::Explicit,
            owner: None,
        },
    );
    let entry = function.id.clone();
    let functions = vec![LinkedScalarFunction {
        function,
        origin: IdentityOrigin::Explicit,
    }];
    let parts = LinkedOwnedDataParts {
        permits: Vec::new(),
        types,
        interfaces: Vec::new(),
        declaration_facts: facts,
        function_templates: Vec::new(),
        function_instances: Vec::new(),
    };
    if old {
        crate::hir::workspace_link::legacy_nominal_before::
            link_owned_data_api_workspace_before_legacy_coordinates(
                "final.legacy".to_owned(), entry, functions, parts,
            )
    } else {
        crate::hir::workspace_link::link_owned_data_api_workspace(
            "final.legacy".to_owned(),
            entry,
            functions,
            parts,
        )
    }
}
fn left_case(types: &[ResolvedTypeDeclaration]) -> &crate::hir::ResolvedVariantCaseDeclaration {
    types
        .iter()
        .find_map(|ty| match &ty.kind {
            ResolvedTypeDeclarationKind::Variant { cases } if ty.id.as_str() == "choice.type" => {
                assert!(cases.is_legacy_shared() && !cases.is_shared());
                Some(&cases[0])
            }
            _ => None,
        })
        .unwrap()
}
#[test]
fn legacy_final_constructor_preserves_complete_old_hir_wire_and_mutation_isolation() {
    let (types, facts) = fixture(false);
    let function = main_function();
    let old = final_link(types.clone(), facts.clone(), function.clone(), true).unwrap();
    let mut current = final_link(types.clone(), facts, function, false).unwrap();
    assert_eq!(current, old);
    assert_eq!(
        crate::cache_codec::encode(&current).unwrap(),
        crate::cache_codec::encode(&old).unwrap()
    );
    let decoded: ResolvedProgram =
        crate::cache_codec::decode(&crate::cache_codec::encode(&current).unwrap()).unwrap();
    assert_eq!(decoded, old);
    assert_eq!(
        crate::graph::to_hir_json(&current, "final-legacy-revision").unwrap(),
        crate::graph::to_hir_json(&old, "final-legacy-revision").unwrap()
    );
    let id = DeclarationId::new("choice.left");
    let ptr = left_case(&types).fields.as_ptr();
    assert_eq!(ptr, current.declarations.case_fields(&id).unwrap().as_ptr());
    assert_eq!(ptr, left_case(&current.types).fields.as_ptr());
    assert_ne!(ptr, old.declarations.case_fields(&id).unwrap().as_ptr());
    let sibling = current.clone();
    current.declarations.case_fields.get_mut(&id).unwrap()[0]
        .name
        .push_str(".index");
    assert_eq!(left_case(&types).fields[0].name, "x");
    assert_eq!(left_case(&current.types).fields[0].name, "x");
    assert_eq!(sibling.declarations.case_fields(&id).unwrap()[0].name, "x");
    let choice = current
        .types
        .iter_mut()
        .find(|ty| ty.id.as_str() == "choice.type")
        .unwrap();
    let ResolvedTypeDeclarationKind::Variant { cases } = &mut choice.kind else {
        panic!("variant")
    };
    for case in cases {
        for field in &mut case.fields {
            field.name.push_str(".hir");
        }
    }
    assert_eq!(
        current.declarations.case_fields(&id).unwrap()[0].name,
        "x.index"
    );
    assert_eq!(left_case(&sibling.types).fields[0].name, "x");
    assert_eq!(old.declarations.case_fields(&id).unwrap()[0].name, "x");
}
#[test]
fn legacy_final_constructor_retains_all_original_fact_errors_and_partial_map_order() {
    let (types, facts) = fixture(false);
    for scalar in [false, true] {
        for mutation in 0..5 {
            let mut supplied = facts.clone();
            match mutation {
                0 => {
                    supplied.remove(&DeclarationId::new("choice.x"));
                }
                1 => {
                    supplied
                        .get_mut(&DeclarationId::new("choice.x"))
                        .unwrap()
                        .kind = DeclarationKind::Function;
                }
                2 => {
                    supplied
                        .get_mut(&DeclarationId::new("choice.x"))
                        .unwrap()
                        .owner = None;
                }
                3 => {
                    supplied.remove(&DeclarationId::new("choice.right"));
                    supplied.remove(&DeclarationId::new("choice.x"));
                }
                _ => {
                    supplied.get_mut(&DeclarationId::new("row.x")).unwrap().kind =
                        DeclarationKind::Function;
                    supplied.remove(&DeclarationId::new("choice.x"));
                }
            }
            let (old, old_error) = extend(&types, &supplied, true, scalar);
            let (current, error) = extend(&types, &supplied, false, scalar);
            let mut before = DeclarationIndex::default();
            let before_error = if scalar {
                before.extend_linked_scalar_data_before_legacy_coordinates(
                    &types,
                    &[],
                    &[],
                    &[],
                    &supplied,
                )
            } else {
                before.extend_linked_owned_data_before_legacy_coordinates(
                    &types,
                    &[],
                    &[],
                    &[],
                    &supplied,
                )
            };
            assert_eq!(
                error, before_error,
                "complete immediate predecessor diagnostics"
            );
            assert_eq!(
                current, before,
                "complete immediate predecessor partial maps"
            );
            assert!(error.is_err());
            assert_eq!(
                error, old_error,
                "complete six fields and competing first failure"
            );
            assert_eq!(current, old, "all partial facts after exact first failure");
            assert_eq!(
                crate::cache_codec::encode(&current).unwrap(),
                crate::cache_codec::encode(&old).unwrap()
            );
            if !scalar {
                let old = final_link(types.clone(), supplied.clone(), main_function(), true);
                let current = final_link(types.clone(), supplied, main_function(), false);
                assert_eq!(
                    current, old,
                    "actual complete finalizer error, not only index helper"
                );
            }
        }
    }
}
#[test]
fn legacy_final_constructor_observes_real_owned_baseline_and_whole_drop_both_orders() {
    // The process prelude is warm before each symmetric constructor-only window.
    crate::prelude::declarations();
    let (types, facts) = fixture(false);
    let wire = crate::cache_codec::encode(&types).unwrap();
    let owned: Vec<ResolvedTypeDeclaration> = crate::cache_codec::decode(&wire).unwrap();
    let function = main_function();
    let mut costs = Vec::new();
    for input in [&owned, &types] {
        for old in [true, false] {
            let ((), observed) = measure(|| {
                let linked = final_link((*input).clone(), facts.clone(), function.clone(), old);
                assert!(linked.is_ok());
                drop(linked);
            });
            // Isolate this no-payer index receiver from the finalizer's other
            // independently metered validation/replay operations.
            let ((), refused, used, first) =
                crate::bounded_output::with_limit_usage_refusal(0, || {
                    let (index, result) = extend(input, &facts, old, false);
                    assert!(result.is_ok());
                    drop(index);
                });
            assert!(!refused && first.is_none());
            assert_eq!(
                used, 0,
                "explicit unfunded receiver, never ambient paid authority"
            );
            assert!(!observed.invalid);
            assert_eq!(observed.live, 0);
            assert_eq!(observed.allocated, observed.freed);
            costs.push(observed);
        }
    }
    assert_eq!(
        costs[0].allocated, costs[1].allocated,
        "genuine decoded Owned branch is unchanged"
    );
    assert!(
        costs[3].allocated < costs[2].allocated,
        "same genuine Legacy input, whole original receiver observed: {costs:?}"
    );
    eprintln!("final-link-owned-before/current-legacy-before/current={costs:?}");
    for input_first in [false, true] {
        let ((), whole) = measure(|| {
            let (types, facts) = fixture(false);
            let mut current = final_link(types.clone(), facts, main_function(), false).unwrap();
            let sibling = current.clone();
            let id = DeclarationId::new("choice.left");
            current.declarations.case_fields.get_mut(&id).unwrap()[0].ty = ResolvedType::Bool;
            if input_first {
                drop(types);
                drop(current);
                drop(sibling);
            } else {
                drop(sibling);
                drop(current);
                drop(types);
            }
        });
        assert!(!whole.invalid);
        assert_eq!(whole.live, 0);
        assert_eq!(whole.allocated, whole.freed);
    }
}
#[test]
fn legacy_final_case_coordinates_and_detached_children_drop_512_without_new_backing() {
    crate::prelude::declarations();
    for input_first in [false, true] {
        let ((), whole) = measure(|| {
            let (mut types, facts) = fixture(false);
            let cases = types
                .iter_mut()
                .find_map(|ty| match &mut ty.kind {
                    ResolvedTypeDeclarationKind::Variant { cases } => Some(cases),
                    _ => None,
                })
                .unwrap();
            let mut ty = ResolvedType::I64;
            for _ in 0..512 {
                ty = ResolvedType::Nominal {
                    declaration: DeclarationId::new("synthetic.depth"),
                    arguments: vec![ty],
                };
            }
            cases[0].fields[0].ty = ty;
            let replacement = NominalPayload::from_legacy_vec_unfunded(&mut **cases);
            *cases = replacement;
            let (mut current, result) = extend(&types, &facts, false, false);
            assert!(result.is_ok());
            let sibling = current.clone();
            let id = DeclarationId::new("choice.left");
            assert_eq!(
                current.case_fields(&id).unwrap().as_ptr(),
                left_case(&types).fields.as_ptr()
            );
            // This real CaseFields mutation detaches a deep independent Owned child.
            current.case_fields.get_mut(&id).unwrap()[0]
                .name
                .push_str(".detached");
            assert_eq!(sibling.case_fields(&id).unwrap()[0].name, "x");
            let mut cursor = &sibling.case_fields(&id).unwrap()[0].ty;
            let mut depth = 0;
            while let ResolvedType::Nominal { arguments, .. } = cursor {
                depth += 1;
                cursor = &arguments[0];
            }
            assert_eq!(depth, 512);
            let before = current_metrics();
            if input_first {
                drop(types);
                drop(current);
                drop(sibling);
            } else {
                drop(sibling);
                drop(current);
                drop(types);
            }
            drop(facts);
            assert_eq!(
                current_metrics().allocated,
                before.allocated,
                "complete last-owner Drop allocates nothing"
            );
        });
        assert!(!whole.invalid);
        assert_eq!(whole.live, 0);
        assert_eq!(whole.allocated, whole.freed);
    }
}

//! Linked owned-data closure registration for the declaration index.
//!
//! The Project owned-data profiles link one exact closure instead of whole
//! modules, so this route rebuilds the index from the supplied declarations
//! and their Phase-A facts alone. It lives beside its owner so the declaration
//! index stays inside its module-size budget.

use super::super::DeclarationIndex;
use crate::hir::*;

impl DeclarationIndex {
    /// Extend the canonical compiler prelude with exactly one authenticated
    /// Project-v8 closure. Every retained declaration must have one matching
    /// Phase-A fact and every supplied fact must be consumed; this prevents
    /// both declaration omission and unrelated whole-module leakage.
    pub(in crate::hir) fn extend_linked_owned_data_before_legacy_coordinates(
        &mut self,
        types: &[ResolvedTypeDeclaration],
        interfaces: &[ResolvedInterface],
        functions: &[ResolvedFunction],
        templates: &[ResolvedFunctionTemplate],
        facts: &BTreeMap<DeclarationId, LinkedDeclarationFact>,
    ) -> Result<(), Diagnostic> {
        self.extend_linked_data_before_legacy_coordinates(types, interfaces, functions, templates, facts, false)
    }

    pub(in crate::hir) fn extend_linked_scalar_data_before_legacy_coordinates(
        &mut self,
        types: &[ResolvedTypeDeclaration],
        interfaces: &[ResolvedInterface],
        functions: &[ResolvedFunction],
        templates: &[ResolvedFunctionTemplate],
        facts: &BTreeMap<DeclarationId, LinkedDeclarationFact>,
    ) -> Result<(), Diagnostic> {
        self.extend_linked_data_before_legacy_coordinates(types, interfaces, functions, templates, facts, true)
    }

    fn extend_linked_data_before_legacy_coordinates(
        &mut self,
        types: &[ResolvedTypeDeclaration],
        interfaces: &[ResolvedInterface],
        functions: &[ResolvedFunction],
        templates: &[ResolvedFunctionTemplate],
        facts: &BTreeMap<DeclarationId, LinkedDeclarationFact>,
        admit_classes: bool,
    ) -> Result<(), Diagnostic> {
        fn require_fact<'a>(
            facts: &'a BTreeMap<DeclarationId, LinkedDeclarationFact>,
            used: &mut BTreeSet<DeclarationId>,
            id: &DeclarationId,
            kind: DeclarationKind,
            owner: Option<&DeclarationId>,
        ) -> Result<&'a LinkedDeclarationFact, Diagnostic> {
            let fact = facts.get(id).ok_or_else(|| {
                Diagnostic::io(
                    "SPX-G173",
                    format!("linked declaration `{id}` has no authenticated Phase-A fact"),
                )
            })?;
            if fact.kind != kind || fact.owner.as_ref() != owner {
                return Err(Diagnostic::io(
                    "SPX-G173",
                    format!("linked declaration `{id}` disagrees with its Phase-A fact"),
                ));
            }
            if !used.insert(id.clone()) {
                return Err(Diagnostic::io(
                    "SPX-G173",
                    format!("linked declaration `{id}` is retained more than once"),
                ));
            }
            Ok(fact)
        }

        let mut used = BTreeSet::new();
        for declaration in types {
            let kind = match &declaration.kind {
                ResolvedTypeDeclarationKind::Record { .. } => DeclarationKind::Record,
                ResolvedTypeDeclarationKind::Variant { .. } => DeclarationKind::Variant,
                ResolvedTypeDeclarationKind::Class { .. } if admit_classes => {
                    DeclarationKind::Class
                }
                ResolvedTypeDeclarationKind::Resource { .. }
                    if (admit_classes
                        && workspace_link::native_owner::admitted_resource(
                            declaration,
                            interfaces,
                        ))
                        || workspace_link::native_owner::admitted_ri06_regex_resource(
                            declaration,
                            interfaces,
                        ) =>
                {
                    DeclarationKind::Resource
                }
                ResolvedTypeDeclarationKind::Class { .. }
                | ResolvedTypeDeclarationKind::Resource { .. } => {
                    return Err(Diagnostic::io(
                        "SPX-G172",
                        format!(
                            "linked owned-data type `{}` is outside the shared record/variant target profile",
                            declaration.id
                        ),
                    ));
                }
            };
            let fact = require_fact(facts, &mut used, &declaration.id, kind, None)?;
            if self.declarations.contains_key(&declaration.id) {
                return Err(Diagnostic::io(
                    "SPX-G173",
                    format!(
                        "linked type `{}` aliases the compiler prelude",
                        declaration.id
                    ),
                ));
            }
            self.insert_top_level(
                declaration.name.clone(),
                declaration.id.clone(),
                kind,
                fact.origin,
            );
            self.type_parameters
                .insert(declaration.id.clone(), declaration.type_parameters.clone());

            match &declaration.kind {
                ResolvedTypeDeclarationKind::Record { fields }
                | ResolvedTypeDeclarationKind::Class { fields, .. } => {
                    for field in fields {
                        let fact = require_fact(
                            facts,
                            &mut used,
                            &field.id,
                            DeclarationKind::Field,
                            Some(&declaration.id),
                        )?;
                        self.insert_field_view(declaration.id.clone(), field, fact.origin);
                    }
                    self.record_fields
                        .insert(declaration.id.clone(), fields.clone());
                }
                ResolvedTypeDeclarationKind::Variant { cases } => {
                    for (ordinal, case) in cases.iter().enumerate() {
                        let fact = require_fact(
                            facts,
                            &mut used,
                            &case.id,
                            DeclarationKind::VariantCase,
                            Some(&declaration.id),
                        )?;
                        self.insert_case(
                            declaration.id.clone(),
                            case.name.clone(),
                            case.id.clone(),
                            fact.origin,
                        );
                        for field in &case.fields {
                            let fact = require_fact(
                                facts,
                                &mut used,
                                &field.id,
                                DeclarationKind::CaseField,
                                Some(&case.id),
                            )?;
                            self.insert_case_field_view(case.id.clone(), field, fact.origin);
                        }
                        // Only an already acquired immutable owner can back
                        // coordinates. Legacy/decoded values retain their own
                        // complete field facts; this route grants no payer.
                        let fields: nominal_payload::map::CaseFields = if cases.is_shared() {
                            nominal_payload::map::CaseFields::canonical(cases.clone(), ordinal)
                        } else {
                            case.fields.clone().into()
                        };
                        self.case_fields.insert(case.id.clone(), fields);
                    }
                    self.variant_cases
                        .insert(declaration.id.clone(), cases.clone());
                }
                ResolvedTypeDeclarationKind::Resource { drop } => {
                    let fact = require_fact(
                        facts,
                        &mut used,
                        &drop.id,
                        DeclarationKind::ResourceDrop,
                        Some(&declaration.id),
                    )?;
                    self.insert_owned_declaration(
                        declaration.id.clone(),
                        "drop".to_owned(),
                        drop.id.clone(),
                        DeclarationKind::ResourceDrop,
                        fact.origin,
                    );
                }
            }
        }

        for interface in interfaces {
            let fact = require_fact(
                facts,
                &mut used,
                &interface.id,
                DeclarationKind::Interface,
                None,
            )?;
            if self.declarations.contains_key(&interface.id) {
                return Err(Diagnostic::io(
                    "SPX-G173",
                    format!(
                        "linked interface `{}` aliases the compiler prelude",
                        interface.id
                    ),
                ));
            }
            self.insert_top_level(
                interface.name.clone(),
                interface.id.clone(),
                DeclarationKind::Interface,
                fact.origin,
            );
            for import in &interface.imports {
                let fact = require_fact(
                    facts,
                    &mut used,
                    &import.id,
                    DeclarationKind::Import,
                    Some(&interface.id),
                )?;
                if self
                    .imports_by_key
                    .insert(import.import_key.clone(), import.id.clone())
                    .is_some()
                {
                    return Err(Diagnostic::io(
                        "SPX-G173",
                        "linked import keys are not unique",
                    ));
                }
                if import.native_rust
                    && self
                        .native_rust_imports_by_name
                        .insert(import.name.clone(), import.id.clone())
                        .is_some()
                {
                    return Err(Diagnostic::io(
                        "SPX-G173",
                        "linked Native Rust import names are not unique",
                    ));
                }
                self.insert_owned_declaration(
                    interface.id.clone(),
                    import.name.clone(),
                    import.id.clone(),
                    DeclarationKind::Import,
                    fact.origin,
                );
            }
        }

        for function in functions {
            let owner = admit_classes
                .then(|| facts.get(&function.id).and_then(|fact| fact.owner.as_ref()))
                .flatten();
            let fact = require_fact(
                facts,
                &mut used,
                &function.id,
                DeclarationKind::Function,
                owner,
            )?;
            if self.declarations.contains_key(&function.id) {
                return Err(Diagnostic::io(
                    "SPX-G173",
                    format!(
                        "linked function `{}` aliases the compiler prelude",
                        function.id
                    ),
                ));
            }
            if let Some(owner) = owner {
                self.insert_owned_declaration(
                    owner.clone(),
                    function.name.clone(),
                    function.id.clone(),
                    DeclarationKind::Function,
                    fact.origin,
                );
            } else {
                self.insert_top_level(
                    function.name.clone(),
                    function.id.clone(),
                    DeclarationKind::Function,
                    fact.origin,
                );
            }
            self.type_parameters.insert(function.id.clone(), Vec::new());
        }
        // A generic template owns an ordinary function identity; only its
        // canonical type-parameter metadata separates it from a monomorphic
        // declaration, and canonical validation reconstructs that metadata
        // from this index rather than from the retained template body.
        for template in templates {
            let fact = require_fact(
                facts,
                &mut used,
                &template.id,
                DeclarationKind::Function,
                None,
            )?;
            if self.declarations.contains_key(&template.id) {
                return Err(Diagnostic::io(
                    "SPX-G173",
                    format!(
                        "linked generic template `{}` aliases the compiler prelude",
                        template.id
                    ),
                ));
            }
            self.insert_top_level(
                template.name.clone(),
                template.id.clone(),
                DeclarationKind::Function,
                fact.origin,
            );
            self.type_parameters
                .insert(template.id.clone(), template.type_parameters.clone());
        }
        if interfaces
            .iter()
            .flat_map(|interface| &interface.imports)
            .filter(|import| import.native_rust)
            .any(|import| self.functions_by_name.contains_key(&import.name))
        {
            return Err(Diagnostic::io(
                "SPX-B107",
                "Native Rust Interop declaration set is unsupported: symbol collision",
            ));
        }
        if used.len() != facts.len() {
            return Err(Diagnostic::io(
                "SPX-G173",
                "linked declaration facts contain an unrelated declaration",
            ));
        }
        Ok(())
    }
}

//! Complete a417 final constructor; only entry name and full old index call differ.
use super::{
    analyze_byte_data_capacity, compiler_prelude, derive_byte_slice_provenance,
    link_error, rebuild_cleanup_metadata, validate, BTreeSet, DeclarationId,
    Diagnostic, IdentityOrigin, LinkedOwnedDataParts, LinkedScalarFunction,
    ResolvedProgram, ResolvedType,
};
pub(crate) fn link_owned_data_api_workspace_before_legacy_coordinates(
    module: String,
    entrypoint: DeclarationId,
    mut linked_functions: Vec<LinkedScalarFunction>,
    parts: LinkedOwnedDataParts,
) -> Result<ResolvedProgram, Diagnostic> {
    if linked_functions.is_empty() {
        return Err(link_error("workspace owned-data closure has no functions"));
    }
    linked_functions.sort_by(|left, right| left.function.id.cmp(&right.function.id));
    let mut seen = BTreeSet::new();
    let mut entry_origin = None;
    for linked in &linked_functions {
        if !seen.insert(linked.function.id.clone()) {
            return Err(link_error(format!(
                "workspace owned-data closure duplicates function `{}`",
                linked.function.id
            )));
        }
        if linked.function.id == entrypoint {
            entry_origin = Some(linked.origin);
            if linked.function.name != "main"
                || !linked.function.params.is_empty()
                || linked.function.return_type != ResolvedType::I64
            {
                return Err(link_error(
                    "workspace owned-data entry point must be an authored `fn main() -> i64`",
                ));
            }
        }
    }
    if entry_origin != Some(IdentityOrigin::Explicit) {
        return Err(link_error(
            "workspace owned-data entry point must have an explicit authored identity",
        ));
    }

    let functions = linked_functions
        .drain(..)
        .map(|linked| linked.function)
        .collect::<Vec<_>>();
    let uses_private_collections = functions.iter().any(|f| {
        crate::map_ops::is_collection(&f.return_type)
            || f.params
                .iter()
                .any(|p| crate::map_ops::is_collection(&p.ty))
    }) || functions.iter().any(|f| {
        f.requires
            .iter()
            .chain(std::iter::once(&f.body))
            .chain(&f.ensures)
            .any(|root| {
                let mut found = false;
                crate::hir::visit_resolved_calls(root, &mut |callee, _, _| {
                    found |= crate::map_ops::by_id(callee.as_str()).is_some()
                });
                found
            })
    }) || parts
        .types
        .iter()
        .any(|t| crate::map_ops::is_declaration(t.id.as_str()));
    let uses_stream = functions
        .iter()
        .any(crate::stdin_stream_ops::resolved_function_uses);
    let uses_vec = compiler_prelude::owned_data_uses_vec(&functions, &parts);
    let (mut declarations, mut types) = if uses_private_collections && uses_vec {
        compiler_prelude::workspace_compiler_prelude_for_stream_data_collections()?
    } else if uses_private_collections {
        compiler_prelude::workspace_compiler_prelude_for_collections()?
    } else if uses_stream && uses_vec {
        compiler_prelude::workspace_compiler_prelude_for_stream_data()?
    } else if uses_stream {
        compiler_prelude::workspace_compiler_prelude_for_stream()?
    } else {
        compiler_prelude::selected_for_owned_data(&functions, &parts)?
    };
    declarations.extend_linked_owned_data_before_legacy_coordinates(
        &parts.types,
        &parts.interfaces,
        &functions,
        &parts.function_templates,
        &parts.declaration_facts,
    )?;
    declarations.byte_slice_roots = derive_byte_slice_provenance(&functions, &declarations)?;
    if !declarations.populate_type_facts() {
        return Err(link_error(
            "workspace owned-data linker could not construct exact type facts",
        ));
    }
    types.extend(parts.types);
    let mut linked = ResolvedProgram {
        module,
        permits: parts.permits,
        agents: Vec::new(),
        entrypoint,
        declarations,
        types,
        interfaces: parts.interfaces,
        function_templates: parts.function_templates,
        functions,
        function_instances: parts.function_instances,
    };
    analyze_byte_data_capacity(&linked)?;
    rebuild_cleanup_metadata(&mut linked)?;
    validate(&linked)?;
    Ok(linked)
}
